            throw new IllegalArgumentException("Directory does not exist or is not a directory: " + dir);
        }

        try {
            for (File file : dirFile.listFiles()) {
                if (file.isFile() && file.getName().endsWith(".jar")) {
                    URL jarUrl = file.toURI().toURL();
                    cpV.add(jarUrl);
                }
            }

            // If the directory is a system classpath
            if (System.getProperty("java.home") != null) {
                String systemClasspathEnv = System.getProperty("java.classpath");
                if (systemClasspathEnv != null) {
                    String[] systemClasspathPaths = systemClasspathEnv.split(File.pathSeparator);
                    for (String path : systemClasspathPaths) {
                        URL systemClasspathUrl = new File(path).toURI().toURL();
                        cpV.add(systemClasspathUrl);
                    }
                }
            }
        } catch (Exception e) {
            System.err.println("Error adding jar files to classpath: " + e.getMessage());
