public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    List<Class<?>> arguments = new ArrayList<>();
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

        for (Type typeArgument : actualTypeArguments) {
            if (typeArgument instanceof Class<?>) {
                arguments.add((Class<?>) typeArgument);
            } else {
                throw new IllegalArgumentException("Actual type argument is not a class");
            }
        }
    } else {
        throw new IllegalArgumentException("Generic type must be parameterized");
    }

    if (arguments.size() != targetType.getParameterCount()) {
        throw new IllegalArgumentException("The number of arguments in the generic type and target type do not match");
    }

    return arguments.toArray(new Class<?>[arguments.size()]);
}

