public long readLong(final int offset) throws IOException {
    // validate input
    if (offset < 0 || offset >= this.data.length) {
        throw new IllegalArgumentException("Invalid offset");
    }

    // handle potential invalid inputs
    if (this.data[offset] == 0x0) {
        if ((this.data[offset + 1] & 0xFF) == 0x80) {
            throw new IllegalArgumentException("Invalid first byte of long");
        }
    } else if ((this.data[offset] & 0xFF) == 0xF0) {
        if ((this.data[offset + 1] & 0xFF) == 0x80) {
            throw new IllegalArgumentException("Invalid first two bytes of long");
        } else if ((this.data[offset + 2] & 0xFF) == 0x80) {
            throw new IllegalArgumentException("Invalid first three bytes of long");
        } else if ((this.data[offset + 3] & 0xFF) == 0x80) {
            throw new IllegalArgumentException("Invalid first four bytes of long");
        } else if ((this.data[offset + 4] & 0xFF) == 0x80) {
            throw new IllegalArgumentException("Invalid first five bytes of long");
        } else if ((this.data[offset + 5] & 0xFF) == 0x80) {
            throw new IllegalArgumentException("Invalid first six bytes of long");
        } else if ((this.data[offset + 6] & 0xFF) == 0x80) {
            throw new IllegalArgumentException("Invalid first seven bytes of long");
        } else if ((this.data[offset + 7] & 0xFF) == 0x80) {
            throw new IllegalArgumentException("Invalid first eight bytes of long");
        }
    }

    // read the long value
    if ((this.data[offset] & 0xF0) == 0x0) {
        // single byte long
        return this.data[offset] & 0xFF;
    } else if ((this.data[offset] & 0xF0) == 0x80) {
        // two byte long
        return ((this.data[offset] & 0xFF) << 8) | this.data[offset + 1];
    } else if ((this.data[offset] & 0xF0) == 0xC0) {
        // three byte long
        return ((this.data[offset] & 0xFF) << 16) | ((this.data[offset + 1] & 0xFF) << 8) | this.data[offset + 2];
    } else if ((this.data[offset] & 0xF0) == 0xE0) {
        // four byte long
        return ((this.data[offset] & 0xFF) << 24) | ((this.data[offset + 1] & 0xFF) << 16) | ((this.data[offset + 2] & 0xFF) << 8) | this.data[offset + 3];
    } else {
        // five byte long
        return ((this.data[offset] & 0xFF) << 32) | ((this.data[offset + 1] & 0xFF) << 24) | ((this.data[offset + 2] & 0xFF) << 16) | ((this.data[offset + 3] & 0xFF) << 8) | this.data[offset + 4];
    }
}

public boolean equals(final byte[] data, int offset, final int len) throws IllegalArgumentException {
    if (data == null) {
        throw new IllegalArgumentException("data cannot be null");
    }
    if (offset < 0 || offset > data.length) {
        throw new IllegalArgumentException("offset cannot be out of bounds");
    }
    if (len < 0 || offset + len > data.length) {
        throw new IllegalArgumentException("len cannot be out of bounds");
    }
    if (data.length % 2 != 0) {
        throw new IllegalArgumentException("data length must be even");
    }
    for (int i = 0; i < len; i++) {
        if (data[offset + i] != data[offset + len - i - 1]) {
            return false;
        }
    }
    return true;
}

