public class TimeRangeSplitter {

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        // Check if the input values are valid
        if (start >= end) {
            throw new IllegalArgumentException("Start time must be less than end time");
        }

        // Calculate the duration of one fetch data
        long fetchDataDuration = 1000; // Example duration of 1 second

        // Calculate the number of time ranges needed
        long rangeCount = (end - start + fetchDataDuration - 1) / fetchDataDuration;

        // Create and return the list of time ranges
        List<TimeRange> timeRanges = new ArrayList<>();
        for (int i = 0; i < rangeCount; i++) {
            long startTime = start + i * fetchDataDuration;
            long endTime = Math.min(start + (i + 1) * fetchDataDuration, end);
            timeRanges.add(new TimeRange(startTime, endTime));
        }

        return timeRanges;
    }
}

