public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
    if (str == null || str.length() == 0) {
        throw new IllegalArgumentException("String cannot be null or empty");
    }
    if (index < 0 || index >= str.length()) {
        throw new IllegalArgumentException("Index is out of bounds");
    }
    if (len < 0) {
        throw new IllegalArgumentException("Length cannot be negative");
    }
    if (index + len > str.length()) {
        throw new IllegalArgumentException("Index and length combination creates invalid span");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        if ((str.charAt(i) & 0x80) != 0) {
            size++; // 1 byte for most chars
            if ((str.charAt(i) & 0xC0) != 0x80) {
                size++; // 1 byte for continuation bytes
            }
        }
        if ((str.charAt(i) & 0xE0) == 0xE0) { // Two-byte character
            size += 2;
            if ((str.charAt(i + 1) & 0xC0) != 0x80 || (str.charAt(i + 2) & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid two-byte character at index " + i);
            }
        }
        if ((str.charAt(i) & 0xF0) == 0xF0) { // Three-byte character
            size += 3;
            if (str.length() < i + 3 || ((str.charAt(i + 1) & 0xC0) != 0x80 || (str.charAt(i + 2) & 0xC0) != 0x80 || (str.charAt(i + 3) & 0xC0) != 0x80)) {
                throw new IllegalArgumentException("Invalid three-byte character at index " + i);
            }
        }
    }
    return size;
}

