            return c - 'A' + 10; // A -> Z 10 -> 35
        }
        if ('a' <= c && c <= 'z') {
            return c - 'a' + 10; // a -> z 10 -> 35
        }
    }
    throw new IllegalArgumentException("Invalid input: must be a digit or letter");
}

