    if (bucketsByLabel == null || labels == null || labels.isEmpty() || minLabel < 0) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Find the bucket with the label minLabel
    Set<Integer> targetBucket = bucketsByLabel.get(minLabel);
    if (targetBucket == null) {
        return; // The bucket does not exist, no need to process
    }

    // Remove all vertices from the target bucket
    targetBucket.clear();

    // Update the labels of vertices to be in bin 0
    for (int i = 0; i < labels.size(); i++) {
        int currentLabel = labels.get(i);
        if (currentLabel > 0) {
            labels.set(i, 0); // Assuming an index of 0 means bin 0
        }
    }

    // Add all vertices back to bin 0
    bucketsByLabel.add(targetBucket);
}

