    private List<Pair<List<Pair<Integer, Integer>>, E>> computeEdgeSeparators(Edge edge) {
        List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();

        // Find all the neighbors of the edge
        List<Node> neighbors = graph.findNeighbors(edge);

        // Iterate over each neighbor and compute minimal separators in its neighborhood
        for (Node neighbor : neighbors) {
            // Compute the minimal separators of the edge relative to the neighbor
            List<Pair<List<Pair<Integer, Integer>>, E>> neighborSeparators = computeNeighborSeparators(edge, neighbor);

            // Add the neighbor separators to the global separator list
            separatorList.addAll(neighborSeparators);
        }

        return separatorList;
    }

    /**
     * Computes the minimal separators of the edge $e$ relative to the neighbor $v$
     * @param edge the edge to compute the minimal separators for
     * @param neighbor the neighbor to compute the minimal separators for
     * @return the list of minimal separators of the edge relative to the neighbor
     */
    private List<Pair<List<Pair<Integer, Integer>>, E>> computeNeighborSeparators(Edge edge, Node neighbor) {
        List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();

        // Find all the nodes in the graph that are adjacent to both the edge and the neighbor
        List<Node> commonNeighbors = graph.findCommonNeighbors(edge, neighbor);

        // Iterate over each common neighbor and compute minimal separators in its neighborhood
        for (Node commonNeighbor : commonNeighbors) {
            // Compute the minimal separators of the edge relative to the common neighbor
            List<Pair<List<Pair<Integer, Integer>>, E>> commonNeighborSeparators = computeCommonNeighborSeparators(edge, commonNeighbor);

            // Add the common neighbor separators to the global separator list
            separatorList.addAll(commonNeighborSeparators);
        }

        return separatorList;
    }
}

