private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || graph.getNumberOfVertices() < vertices.size()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            throw new IllegalArgumentException("Vertex " + v + " not found in the graph");
        }
    }

    if (vertices.size() == 1) {
        return true;
    }

    Set<V> complement = new HashSet<>(graph.getVertices());
    complement.removeAll(vertices);

    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 == v2) continue;
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }

    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
        if (keys == null || keys.isEmpty()) {
            throw new IllegalArgumentException("Input keys must not be null or empty");
        }

        List<Integer> lowerBounds = new ArrayList<>(keys.size());
        int previousMax =(Long.MIN_VALUE).intValue(); // Initialize with the smallest possible integer

        for (K key : keys) {
            int currentMax = key.getMaxValue(); // Assuming getMaxValue() provides the maximum value of the key
            if (currentMax <= previousMax) {
                throw new IllegalArgumentException("Key " + key + " has a maximum value that is not less than the previous key's maximum value");
            }
            lowerBounds.add(currentMax);
            previousMax = currentMax;
        }

        return lowerBounds;
}

