public class KeyUpperBoundFinder {

    /**
     * Finds a minimum lower bound for every key.
     * @param keys a list of keys.
     * @return the computed key upper bound.
     */
    private List<Integer> computeUpperBounds(List<K> keys) {
        // Check for initial empty condition
        if (keys == null || keys.isEmpty()) {
            throw new IllegalArgumentException("The keys list cannot be null or empty.");
        }

        // Find the minimum value from the keys
        Integer minValue = keys.stream().min(Integer::compare).orElse(null);

        // Initialize a list to store the upper bounds
        List<Integer> upperBounds = keys.stream()
                                          .map(key -> Math.max(value, minValue))
                                          .collect(Collectors.toList());

        return upperBounds;
    }
}

