        return -1;
    }
    int indexOfLastSeparator = filename.lastIndexOf('.');
    int indexOfSecondLastSeparator = filename.lastIndexOf('/', indexOfLastSeparator);
    if (indexOfSecondLastSeparator > indexOfLastSeparator) {
        return indexOfLastSeparator;
    } else {
        return indexOfLastSeparator;
    }
}

